import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

type Doc = { id: string; kind: string; status: string };

test("rejecting an extraction requires a note and returns the vendor to the member", { tag: "@REV-06" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three extracted documents
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("REV-06 Vendor"), category: "services", contact_email: "ops@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const uploads: Array<[string, string]> = [
    ["w9", "w9.txt"],
    ["insurance_certificate", "insurance_certificate.txt"],
    ["contract", "contract.txt"],
  ];
  const docs: Doc[] = [];
  for (const [kind, file] of uploads) {
    const res = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    docs.push((await res.json()) as Doc);
  }

  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendorId}/documents`);
      const list = (await res.json()) as Doc[];
      return list.length === 3 && list.every((d) => d.status === "extracted");
    }, { timeout: 60_000 })
    .toBe(true);

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);

  const w9 = docs.find((d) => d.kind === "w9");
  expect(w9).toBeTruthy();
  const extractionRes = await member.get(`/api/documents/${w9!.id}/extraction`);
  expect(extractionRes.status(), await extractionRes.text()).toBe(200);
  const w9Extraction = (await extractionRes.json()) as { id: string };

  // Act: reject without a note
  const withoutNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
    data: { decision: "reject" },
  });

  // Assert: refused, and the refusal points at the note field
  expect(withoutNote.status(), await withoutNote.text()).toBe(422);
  const refusal = (await withoutNote.json()) as { detail?: Array<{ loc: unknown[] }> };
  expect(JSON.stringify(refusal)).toContain("note");

  // Act: reject with a note
  const withNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
    data: { decision: "reject", note: "Tax ID does not match" },
  });
  expect(withNote.status(), await withNote.text()).toBe(200);

  // Assert: vendor returned to the member and the audit trail records the rejection
  const vendorRes = await member.get(`/api/vendors/${vendorId}`);
  expect(vendorRes.status(), await vendorRes.text()).toBe(200);
  expect(((await vendorRes.json()) as { status: string }).status).toBe("rejected");

  const auditRes = await member.get(`/api/vendors/${vendorId}/audit`);
  expect(auditRes.status(), await auditRes.text()).toBe(200);
  const actions = ((await auditRes.json()) as { items: Array<{ action: string }> }).items.map((i) => i.action);
  expect(actions, "audit actions").toContain("extraction.rejected");
});
